import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 2:
        return 'C'
    if n < 5:
        return 'C'
    opp_last = history[-1][1]
    my_last = history[-1][0]
    opp_def = sum(1 for a, b in history if b == 'D')
    my_def = sum(1 for a, b in history if a == 'D')
    last10 = history[-10:]
    opp10 = sum(1 for a, b in last10 if b == 'D')
    if opp10 >= 8:
        return 'D'
    if n >= 90:
        if opp_def >= 70:
            return 'D'
        if opp_def <= 20:
            return 'C'
    if opp_last == 'D' and my_last == 'C':
        if rng.random() < 0.75:
            return 'D'
    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.35:
            return 'C'
    return 'C'
